process.env.USE_MOCK_BLOCKCHAIN = 'true';
process.env.USE_MOCK_IPFS = 'true';
process.env.USE_MOCK_ARWEAVE = 'true';
process.env.USE_MOCK_WATERMARK = 'true';
process.env.USE_MOCK_AI = 'true';
process.env.USE_KMS = 'false';
process.env.DEV_ENCRYPTION_KEY = 'a'.repeat(64);
process.env.NODE_ENV = 'test';

const crypto = require('crypto');
const { SiweMessage } = require('siwe');
const authMiddleware = require('../../src/middleware/auth');
const { registerSink, removeSink, clearSinks } = require('../../src/events/dispatch');

// Helper: create a mock SIWE auth token using the SiweMessage constructor for correct format
function createMockAuthToken(address) {
  const siwe = new SiweMessage({
    domain: 'localhost',
    address: address,
    statement: 'Sign in to NFTmarket',
    uri: 'http://localhost:3000',
    version: '1',
    chainId: 31337,
    nonce: 'test1234',
    issuedAt: new Date().toISOString(),
  });
  const message = siwe.toMessage();
  const signature = '0x' + crypto.createHash('sha256').update(message).digest('hex');
  return Buffer.from(JSON.stringify({ message, signature })).toString('base64');
}

// Minimal mock Express req/res/next
function mockReq(headers = {}) {
  return { headers };
}

function mockRes() {
  const res = {
    statusCode: null,
    body: null,
    status(code) { res.statusCode = code; return res; },
    json(data) { res.body = data; return res; },
  };
  return res;
}

describe('Auth middleware interface contract', () => {
  let capturedEvents;
  let captureSink;

  beforeEach(() => {
    capturedEvents = [];
    captureSink = (event) => capturedEvents.push(event);
    registerSink(captureSink);
  });

  afterEach(() => {
    removeSink(captureSink);
  });

  // ── Module export ──

  test('exports a single function', () => {
    expect(typeof authMiddleware).toBe('function');
  });

  // ── Success path ──

  test('sets req.wallet and req.chainId on valid mock auth', async () => {
    const address = '0x1234567890123456789012345678901234567890';
    const token = createMockAuthToken(address);
    const req = mockReq({ authorization: `Bearer ${token}` });
    const res = mockRes();
    let nextCalled = false;

    await authMiddleware(req, res, () => { nextCalled = true; });

    expect(nextCalled).toBe(true);
    expect(req.wallet).toBe(address.toLowerCase());
    expect(req.chainId).toBeDefined();
  });

  test('dispatches auth.verified event on success', async () => {
    const address = '0x1234567890123456789012345678901234567890';
    const token = createMockAuthToken(address);
    const req = mockReq({ authorization: `Bearer ${token}` });
    const res = mockRes();

    await authMiddleware(req, res, () => {});

    const authEvents = capturedEvents.filter(e => e.type === 'auth.verified');
    expect(authEvents.length).toBe(1);
    expect(authEvents[0].wallet).toBe(address.toLowerCase());
    expect(authEvents[0]).toHaveProperty('chainId');
    expect(authEvents[0]).toHaveProperty('timestamp');
  });

  // ── Failure paths ──

  test('returns 401 when no authorization header', async () => {
    const req = mockReq({});
    const res = mockRes();
    let nextCalled = false;

    await authMiddleware(req, res, () => { nextCalled = true; });

    expect(nextCalled).toBe(false);
    expect(res.statusCode).toBe(401);
    expect(res.body.code).toBe('UNAUTHORIZED');
  });

  test('returns 401 for invalid token format', async () => {
    const req = mockReq({ authorization: 'Bearer not-valid-base64!!!' });
    const res = mockRes();
    let nextCalled = false;

    await authMiddleware(req, res, () => { nextCalled = true; });

    expect(nextCalled).toBe(false);
    expect(res.statusCode).toBe(401);
  });

  test('returns 401 when message or signature missing', async () => {
    const token = Buffer.from(JSON.stringify({ message: 'test' })).toString('base64');
    const req = mockReq({ authorization: `Bearer ${token}` });
    const res = mockRes();
    let nextCalled = false;

    await authMiddleware(req, res, () => { nextCalled = true; });

    expect(nextCalled).toBe(false);
    expect(res.statusCode).toBe(401);
    expect(res.body.code).toBe('INVALID_TOKEN');
  });

  test('dispatches auth.failed event on failure', async () => {
    const req = mockReq({});
    const res = mockRes();

    await authMiddleware(req, res, () => {});

    const failEvents = capturedEvents.filter(e => e.type === 'auth.failed');
    expect(failEvents.length).toBe(1);
    expect(failEvents[0]).toHaveProperty('reason');
    expect(failEvents[0]).toHaveProperty('timestamp');
  });

  // ── Event generation (not logging) ──

  test('does not log to console directly', async () => {
    const originalLog = console.log;
    const logged = [];
    console.log = (...args) => logged.push(args);

    try {
      const address = '0x1234567890123456789012345678901234567890';
      const token = createMockAuthToken(address);
      const req = mockReq({ authorization: `Bearer ${token}` });
      const res = mockRes();
      await authMiddleware(req, res, () => {});

      // Auth middleware should NOT call console.log directly
      const authLogs = logged.filter(l => l[0]?.toString().includes('[AUTH]'));
      expect(authLogs.length).toBe(0);
    } finally {
      console.log = originalLog;
    }
  });
});
